				if !hasUpdateCouponTemplates {
					if err := auth.CheckAuthorization(ctx, "UpdateCustomerCouponTemplate"); err != nil {
						return item, fmt.Errorf("UpdateCustomerCouponTemplate: %w", err)
					}
					if err := auth.CheckAuthorization(ctx, "CustomerCouponTemplate"); err != nil {
						return item, fmt.Errorf("CustomerCouponTemplate Detail: %w", err)
					}
					hasUpdateCouponTemplates = true
				}

				couponTemplatesInput := utils.StructToMap(*v)
