// ============================================================
// ProductPackage - Delete
// ============================================================

// DeleteProductPackageFunc 执行删除或恢复操作
func DeleteProductPackageFunc(ctx context.Context, r *GeneratedResolver, id string, operationType string, unscoped *bool) (err error) {
	principalID := GetPrincipalIDFromContext(ctx)
	item := &ProductPackage{}
	now := time.Now()
	tx := GetTransaction(ctx)

	// 检查主从关系约束

	// 确定操作类型
	var status int64 = 1
	var isDelete int64 = 2
	if operationType == "recovery" {
		isDelete = 1
		status = 2
	}

	// 获取现有实体
	if err = tx.Unscoped().Table(TableName("product_packages", ctx)).Where("is_delete = ? and id = ?", status, id).First(item).Error; err != nil {
		return err
	}

	deletedAt := now.UnixNano() / 1e6

	// 创建事件记录
	event := NewEvent(EventMetadata{
		Type:        EventTypeDeleted,
		Entity:      "ProductPackage",
		EntityID:    id,
		Date:        deletedAt,
		PrincipalID: principalID,
	})

	// 执行删除或恢复
	if operationType == "recovery" {
		if err := tx.Unscoped().Table(TableName("product_packages", ctx)).Model(&item).Updates(map[string]interface{}{
			"IsDelete":  1,
			"DeletedAt": nil,
			"DeletedBy": nil,
		}).Error; err != nil {
			return err
		}
	} else {
		if unscoped != nil && *unscoped {
			// 物理删除
			if err := tx.Unscoped().Table(TableName("product_packages", ctx)).Model(&item).Delete(item).Error; err != nil {
				return err
			}
		} else {
			// 软删除
			if err := tx.Model(&item).Table(TableName("product_packages", ctx)).Updates(ProductPackage{
				IsDelete:  &isDelete,
				DeletedAt: &deletedAt,
				DeletedBy: principalID,
				UpdatedBy: principalID,
			}).Error; err != nil {
				return err
			}
		}
	}

	// 记录事件
	if len(event.Changes) > 0 {
		AddMutationEvent(ctx, event)
	}

	return
}

// DeleteProductPackages 批量删除 ProductPackage 实体
func (r *GeneratedMutationResolver) DeleteProductPackages(ctx context.Context, id []string, unscoped *bool) (bool, error) {
	ctx = EnrichContextWithMutations(ctx, r.GeneratedResolver)
	done, err := r.Handlers.DeleteProductPackages(ctx, r.GeneratedResolver, id, unscoped)
	if err != nil {
		RollbackMutationContext(ctx, r.GeneratedResolver)
		return done, err
	}
	err = FinishMutationContext(ctx, r.GeneratedResolver)
	return done, err
}

// DeleteProductPackagesHandler 处理批量删除逻辑
func DeleteProductPackagesHandler(ctx context.Context, r *GeneratedResolver, id []string, unscoped *bool) (bool, error) {
	for _, itemID := range id {
		if err := DeleteProductPackageFunc(ctx, r, itemID, "delete", unscoped); err != nil {
			return false, err
		}
	}
	return true, nil
}

// ============================================================
// ProductPackage - Recovery
// ============================================================

// RecoveryProductPackages 批量恢复 ProductPackage 实体
func (r *GeneratedMutationResolver) RecoveryProductPackages(ctx context.Context, id []string) (bool, error) {
	ctx = EnrichContextWithMutations(ctx, r.GeneratedResolver)
	done, err := r.Handlers.RecoveryProductPackages(ctx, r.GeneratedResolver, id)
	if err != nil {
		return done, err
	}
	err = FinishMutationContext(ctx, r.GeneratedResolver)
	return done, err
}

// RecoveryProductPackagesHandler 处理批量恢复逻辑
func RecoveryProductPackagesHandler(ctx context.Context, r *GeneratedResolver, id []string) (bool, error) {
	unscoped := false
	for _, itemID := range id {
		if err := DeleteProductPackageFunc(ctx, r, itemID, "recovery", &unscoped); err != nil {
			return false, err
		}
	}
	return true, nil
}

